// Endless drawers: generated by reverse generation, each verified before use.
const { Packer, Levels } = require('./load')();
let fails = 0;
for (let n = 0; n < (+process.argv[2] || 8); n++) {
  const t = Date.now();
  const pz = Packer.runSync(Levels.endlessGen(n));
  const v = pz && Packer.verify(pz);
  if (!pz || !v.ok) fails++;
  console.log('endless', n, pz ? `${pz.items.length} items  ${pz.W} x ${pz.D} x ${pz.H}  verified ${v.ok}` : 'FAILED', Date.now() - t, 'ms');
}
// all designed levels re-verify from stored data
for (let i = 0; i < Levels.count; i++) { const v = Packer.verify(Levels.designed(i)); if (!v.ok) { fails++; console.log('designed', i + 1, 'FAILED', v.problems); } }
console.log(fails ? fails + ' failures' : 'all puzzles verified solvable');
